select d.nome, count(*) filter (where m.tipo='foto') fotos, count(*) filter (where m.tipo='planta') plantas from public.developments d join public.development_media m on m.development_id=d.id where d.slug like 'pp-%' and d.ativo group by d.nome order by fotos;
